-- EPCOT International Food & Wine Festival 2026: 32 seasonal booths
-- ('kiosk' category) and 124 food/drink items sold at them ('snack'
-- category, booth_id pointing at the booth). 15 items reference 6 booths
-- missing from the source spreadsheet (Funnel Cake, Norway Cart, Shimmering
-- Sips, Connections Eatery Festival Menu, Sommerfest, India) — imported with
-- booth_id left null rather than guessing at their location/dates.
on conflict (id) do update set name=excluded.name, park=excluded.park, category=excluded.category, description=excluded.description, price_label=excluded.price_label, price_mid=excluded.price_mid, location_detail=excluded.location_detail, seasonal=excluded.seasonal, tags=excluded.tags, booth_id=excluded.booth_id, item_type=excluded.item_type;

