insert into catalog_items (id, name, park, category, description, price_label, price_mid, location_detail, dining_tier, cuisine, dining_plan_credits, seasonal, tags, booth_id, item_type) values
  ('kiosk-the-wedge-hosted-by-dairy', 'The Wedge Hosted by Dairy Does More', 'EPCOT', 'kiosk', 'Cheese-focused booth celebrating Wisconsin cheese. Mac and cheese variations, cheese plates, and wine pairings. Opens September 18, closes November 8 — shorter run than most booths.', null, null, 'CommuniCore Hall', null, null, null, '{"festival": "Food & Wine", "start": "09-18", "end": "11-08"}'::jsonb, null, null, null),
  ('kiosk-festival-favorites', 'Festival Favorites', 'EPCOT', 'kiosk', 'A rotating collection of fan-favorite items from past Food & Wine festivals. Opens September 9. Great for returning guests who want to revisit beloved dishes from years past.', null, null, 'CommuniCore Hall', null, null, null, '{"festival": "Food & Wine", "start": "09-09", "end": "11-21"}'::jsonb, null, null, null),
  ('kiosk-brew-wing-lab-at-the-odyssey', 'Brew-Wing Lab at the Odyssey', 'EPCOT', 'kiosk', 'Wings, fried pickles, and an extensive craft beer and hard cider lineup. A party atmosphere in an air-conditioned pavilion. One of the most popular stops for adults at Food & Wine.', null, null, 'World Celebration – Odyssey Events Pavilion', null, null, null, '{"festival": "Food & Wine", "start": "08-27", "end": "11-21"}'::jsonb, null, null, null),
  ('kiosk-coastal-eats', 'Coastal Eats', 'EPCOT', 'kiosk', 'Seafood-focused booth with crab cakes and seafood pot pie. Opens October 2 — plan accordingly if visiting early in the festival.', null, null, 'Near Creations Shop', null, null, null, '{"festival": "Food & Wine", "start": "10-02", "end": "11-21"}'::jsonb, null, null, null),
  ('kiosk-gyozas-of-the-galaxy', 'Gyozas of the Galaxy', 'EPCOT', 'kiosk', 'Dumpling booth near the Guardians ride with creative gyoza variations — chicken, plant-based, and street corn-style. A fun, approachable booth that works well for kids and adults.', null, null, 'Near Guardians of the Galaxy – World Discovery', null, null, null, '{"festival": "Food & Wine", "start": "08-27", "end": "11-21"}'::jsonb, null, null, null),
  ('kiosk-flavors-from-fire', 'Flavors from Fire', 'EPCOT', 'kiosk', 'Smoked and grilled items including skirt steak skewer, smoked corned beef with beer cheese fondue, and the famous Swine Brine cocktail. A perennial crowd-pleaser.', null, null, 'Near Creations Shop', null, null, null, '{"festival": "Food & Wine", "start": "08-27", "end": "11-21"}'::jsonb, null, null, null),
  ('kiosk-the-fry-basket', 'The Fry Basket', 'EPCOT', 'kiosk', 'Creative fry variations including yuca fries, a fry flight, and seasonal sweet potato casserole fries. A fun snack stop, especially for the shareable fry flight.', null, null, 'Near Creations Shop', null, null, null, '{"festival": "Food & Wine", "start": "08-27", "end": "11-21"}'::jsonb, null, null, null),
  ('kiosk-earth-eats', 'Earth Eats', 'EPCOT', 'kiosk', 'Farm-to-table inspired booth near Living with the Land. Braised beef short rib and seasonal produce-forward dishes. Opens October 2.', null, null, 'World Nature – Near The Land Pavilion', null, null, null, '{"festival": "Food & Wine", "start": "10-02", "end": "11-21"}'::jsonb, null, null, null),
  ('kiosk-australia', 'Australia', 'EPCOT', 'kiosk', 'Grilled bushberry shrimp, roasted lamb chop, and berry pavlova alongside Australian wines. The lamb chop is a 30th anniversary legacy item and a fan favorite.', null, null, 'World Showcase – Near Disney Traders', null, null, null, '{"festival": "Food & Wine", "start": "08-27", "end": "11-21"}'::jsonb, null, null, null),
  ('kiosk-mexico', 'Mexico', 'EPCOT', 'kiosk', 'Festival booth outside La Hacienda with pork osso buco tostada, tempura shrimp taco, and berry ice pops. Tequila and mezcal cocktails round out the menu.', null, null, 'World Showcase – Mexico Pavilion', null, null, null, '{"festival": "Food & Wine", "start": "08-27", "end": "11-21"}'::jsonb, null, null, null),
  ('kiosk-china', 'China', 'EPCOT', 'kiosk', 'Dumpling trio, smoked duck bao, and Beijing noodles alongside bubble tea and baijiu cocktails. A reliably strong booth with interesting drink options.', null, null, 'World Showcase – China Pavilion', null, null, null, '{"festival": "Food & Wine", "start": "08-27", "end": "11-21"}'::jsonb, null, null, null),
  ('kiosk-the-alps', 'The Alps', 'EPCOT', 'kiosk', 'Alpine cheese and Austrian wine booth. Warm raclette, tartiflette, and Kirschwasser cake. Opens October 2. Both food items are Emile''s Fromage Montage offerings.', null, null, 'World Showcase – Near Germany Pavilion', null, null, null, '{"festival": "Food & Wine", "start": "10-02", "end": "11-21"}'::jsonb, null, null, null),
  ('kiosk-germany', 'Germany', 'EPCOT', 'kiosk', 'Schinkennudeln (pasta gratin), Wiener Schnitzel, and apple strudel alongside Weihenstephaner Festbier and Selbach-Oster Riesling. The apple strudel is a 30th anniversary legacy item.', null, null, 'World Showcase – Germany Pavilion', null, null, null, '{"festival": "Food & Wine", "start": "08-27", "end": "11-21"}'::jsonb, null, null, null),
  ('kiosk-spain', 'Spain', 'EPCOT', 'kiosk', 'Croquetas de jamón, paella caldoso, and Basque cheesecake. The Basque cheesecake is an Emile''s Fromage Montage item. A consistently excellent booth.', null, null, 'World Showcase – Between Germany and Italy', null, null, null, '{"festival": "Food & Wine", "start": "08-27", "end": "11-21"}'::jsonb, null, null, null),
  ('kiosk-italy', 'Italy', 'EPCOT', 'kiosk', 'Stromboli, chicken marsala, and almond panna cotta alongside Prosecco, Moscato, and an Amaretto Bellini. Strong food quality — one of the better World Showcase booths.', null, null, 'World Showcase – Italy Pavilion', null, null, null, '{"festival": "Food & Wine", "start": "08-27", "end": "11-21"}'::jsonb, null, null, null),
  ('kiosk-hops-barley', 'Hops & Barley', 'EPCOT', 'kiosk', 'American-themed booth returning for 2026 after a 3-year absence. Gulf Coast seafood roll (30th anniversary legacy item), smoked brisket melt, and chocolate pudding cake. New England craft beers.', null, null, 'World Showcase – American Adventure', null, null, null, '{"festival": "Food & Wine", "start": "08-27", "end": "11-21"}'::jsonb, null, null, null),
  ('kiosk-japan', 'Japan', 'EPCOT', 'kiosk', 'Spicy tuna temaki hand roll (30th anniversary legacy item), wagyu beef temaki, and teriyaki chicken bun. Kirinzan sake lemonade and mango-apple fruit pearl drinks are standouts.', null, null, 'World Showcase – Japan Pavilion', null, null, null, '{"festival": "Food & Wine", "start": "08-27", "end": "11-21"}'::jsonb, null, null, null),
  ('kiosk-greece', 'Greece', 'EPCOT', 'kiosk', 'Spanakopita, griddled cheese with pistachios and honey (Emile''s Fromage Montage), and chicken souvlaki gyro. Greek wines and a melon limeade cocktail. One of Food & Wine''s most consistent booths.', null, null, 'World Showcase – Between Japan and Morocco', null, null, null, '{"festival": "Food & Wine", "start": "08-27", "end": "11-21"}'::jsonb, null, null, null),
  ('kiosk-belgium', 'Belgium', 'EPCOT', 'kiosk', 'Beer-braised beef with smoked gouda mashed potatoes, Belgian waffle with cookie butter (30th anniversary legacy item), and a wide Belgian beer selection including strong ales.', null, null, 'World Showcase – Between Morocco and France', null, null, null, '{"festival": "Food & Wine", "start": "08-27", "end": "11-21"}'::jsonb, null, null, null),
  ('kiosk-brazil', 'Brazil', 'EPCOT', 'kiosk', 'Pão de Queijo (Brazilian cheese bread, 30th anniversary Emile''s Fromage Montage item) and plancha-seared shrimp moqueca. Frozen caipirinha is the signature drink.', null, null, 'World Showcase – Between Morocco and France', null, null, null, '{"festival": "Food & Wine", "start": "08-27", "end": "11-21"}'::jsonb, null, null, null),
  ('kiosk-france', 'France', 'EPCOT', 'kiosk', 'Three-cheese spiced brioche, escargot bites in croissant dough (30th anniversary legacy), red wine-braised short ribs, and pistachio crème brûlée. The France booth consistently delivers some of the festival''s best food.', null, null, 'World Showcase – France Pavilion', null, null, null, '{"festival": "Food & Wine", "start": "08-27", "end": "11-21"}'::jsonb, null, null, null),
  ('kiosk-canada', 'Canada', 'EPCOT', 'kiosk', 'The most beloved booth at Food & Wine — Canadian cheddar and bacon soup with pretzel roll (30th anniversary legacy, Emile''s Fromage Montage) and filet mignon with mushrooms. A must-do every year.', null, null, 'World Showcase – Canada Pavilion', null, null, null, '{"festival": "Food & Wine", "start": "08-27", "end": "11-21"}'::jsonb, null, null, null),
  ('kiosk-hawai-i', 'Hawai''i', 'EPCOT', 'kiosk', 'Slow-roasted pork slider (30th anniversary legacy), Hawaiian rice bowl with SPAM, and pineapple cheesecake (Emile''s Fromage Montage). O''ahu Sunrise cocktail and Florida sparkling pineapple wine.', null, null, 'World Showcase – Near Port of Entry', null, null, null, '{"festival": "Food & Wine", "start": "08-27", "end": "11-21"}'::jsonb, null, null, null),
  ('kiosk-la-poutinerie-hosted-by-air', 'La Poutinerie Hosted by Air Canada', 'EPCOT', 'kiosk', 'Creative poutine variations — the Seoul-style bo ssam pork poutine with gochujang gravy and kimchi is the standout item. Spiced apple mule cocktail. A newer booth with a devoted following.', null, null, 'World Showcase – Near Canada Pavilion', null, null, null, '{"festival": "Food & Wine", "start": "08-27", "end": "11-21"}'::jsonb, null, null, null),
  ('kiosk-bramblewood-bites', 'Bramblewood Bites', 'EPCOT', 'kiosk', 'Autumn-themed booth with cider-brined pork tenderloin, cast iron river trout, and brûléed sweet potatoes. One of the more interesting booths for adventurous eaters.', null, null, 'Walkway Between Imagination! and World Showcase', null, null, null, '{"festival": "Food & Wine", "start": "08-27", "end": "11-21"}'::jsonb, null, null, null),
  ('kiosk-milled-mulled', 'Milled & Mulled', 'EPCOT', 'kiosk', 'Harvest and comfort food booth with butternut squash bisque, carrot cake (30th anniversary legacy), and a churro sundae. Fall flavors throughout — cider and harvest ales.', null, null, 'Walkway Between Imagination! and World Showcase', null, null, null, '{"festival": "Food & Wine", "start": "08-27", "end": "11-21"}'::jsonb, null, null, null),
  ('kiosk-forest-field', 'Forest & Field', 'EPCOT', 'kiosk', 'Farm-to-table booth with pumpkin-mascarpone ravioli, a schiacciata focaccia sandwich, and spicy black bean-mushroom chili. One of the better booths for plant-based options.', null, null, 'Walkway Between Imagination! and World Showcase', null, null, null, '{"festival": "Food & Wine", "start": "08-27", "end": "11-21"}'::jsonb, null, null, null),
  ('kiosk-swirled-showcase', 'Swirled Showcase', 'EPCOT', 'kiosk', 'Soft-serve and frozen drinks booth. Liquid nitrogen almond truffle mousse (30th anniversary legacy), soft-serve in waffle cone, frozen Szarlotka (apple pie slushy), and an Irish milkshake with Guinness and Baileys.', null, null, 'Walkway Between Imagination! and World Showcase', null, null, null, '{"festival": "Food & Wine", "start": "08-27", "end": "11-21"}'::jsonb, null, null, null),
  ('kiosk-tangierine-caf-flavors-of-the', 'Tangierine Café: Flavors of the Medina', 'EPCOT', 'kiosk', 'The Morocco pavilion''s year-round quick service running a special festival menu with hummus bowls, falafel wraps, and chocolate-pistachio cookies. Hard cider flight is a popular pairing.', null, null, 'World Showcase – Morocco Pavilion', null, null, null, '{"festival": "Food & Wine", "start": "08-27", "end": "11-21"}'::jsonb, null, null, null),
  ('kiosk-refreshment-outpost-hosted-by', 'Refreshment Outpost Hosted by Coca-Cola', 'EPCOT', 'kiosk', 'African-inspired festival menu at the year-round outpost. Berbere-spiced beef stew, sweet potato mealie pap (30th anniversary plant-based legacy), and South African cream liqueur chocolate mousse.', null, null, 'World Showcase – Between China and Germany', null, null, null, '{"festival": "Food & Wine", "start": "08-27", "end": "11-21"}'::jsonb, null, null, null),
  ('kiosk-regal-eagle-smokehouse-crafts', 'Regal Eagle Smokehouse: Crafts and Drafts', 'EPCOT', 'kiosk', 'The year-round BBQ restaurant running festival-exclusive desserts: blackberry buckle with blackberry gelato and pumpkin pie milkshake.', null, null, 'World Showcase – American Adventure', null, null, null, '{"festival": "Food & Wine", "start": "08-27", "end": "11-21"}'::jsonb, null, null, null),
  ('kiosk-block-hans', 'Block & Hans', 'EPCOT', 'kiosk', 'Year-round beer and pretzel stand with a festival-exclusive spicy strawberry-mango smoothie, available with or without Ole Smoky Strawberry Moonshine.', null, null, 'World Showcase – American Adventure', null, null, null, '{"festival": "Food & Wine", "start": "08-27", "end": "11-21"}'::jsonb, null, null, null)
insert into catalog_items (id, name, park, category, description, price_label, price_mid, location_detail, dining_tier, cuisine, dining_plan_credits, seasonal, tags, booth_id, item_type) values
  ('fw-selection-of-cheeses-with', 'Selection of Cheeses with Accompaniments', 'EPCOT', 'snack', 'Wisconsin cheese plate with accompaniments. Emile''s Fromage Montage eligible.', '$varies', null, null, null, null, null, '{"festival": "Food & Wine", "start": "09-18", "end": "11-08"}'::jsonb, null, 'kiosk-the-wedge-hosted-by-dairy', 'food'),
  ('fw-three-cheese-macaroni-and', 'Three-Cheese Macaroni and Cheese', 'EPCOT', 'snack', 'Smoked cheddar mac with herbed panko.', '~$6', 6.0, null, null, null, null, '{"festival": "Food & Wine", "start": "09-18", "end": "11-08"}'::jsonb, null, 'kiosk-the-wedge-hosted-by-dairy', 'food'),
  ('fw-cheesesteak-macaroni-and', 'Cheesesteak Macaroni and Cheese', 'EPCOT', 'snack', 'Smoked cheddar sauce, shaved beef, peppers, onions, and herbed panko.', '~$6.49', 6.49, null, null, null, null, '{"festival": "Food & Wine", "start": "09-18", "end": "11-08"}'::jsonb, null, 'kiosk-the-wedge-hosted-by-dairy', 'food'),
  ('fw-crab-and-corn-macaroni-and', 'Crab and Corn Macaroni and Cheese', 'EPCOT', 'snack', 'Smoked cheddar with bacon, crab seasoning, roasted corn, herbed panko, and jalapeños. Introduced in 2015 at Farm Fresh.', '~$6.49', 6.49, null, null, null, null, '{"festival": "Food & Wine", "start": "09-18", "end": "11-08"}'::jsonb, ARRAY['30th Anniversary']::text[], 'kiosk-the-wedge-hosted-by-dairy', 'food'),
  ('fw-cannoli-milkshake', 'Cannoli Milkshake', 'EPCOT', 'snack', 'Non-alcoholic. Topped with chocolate shavings, cannoli shell, and maraschino cherry.', '$5.49', 5.49, null, null, null, null, '{"festival": "Food & Wine", "start": "09-18", "end": "11-08"}'::jsonb, null, 'kiosk-the-wedge-hosted-by-dairy', 'drink'),
  ('fw-wine-and-cheese-pairing', 'Wine and Cheese Pairing', 'EPCOT', 'snack', 'Curated wine paired with cheese selection.', '$17.50', 17.5, null, null, null, null, '{"festival": "Food & Wine", "start": "09-18", "end": "11-08"}'::jsonb, null, 'kiosk-the-wedge-hosted-by-dairy', 'drink'),
  ('fw-bo-ssam-pork-belly-lettuce', 'Bo Ssam Pork Belly Lettuce Wraps', 'EPCOT', 'snack', 'Bo ssam pork belly, kimchi slaw, and spicy aïoli. Introduced in 2010 at South Korea booth.', '$6.19', 6.19, null, null, null, null, '{"festival": "Food & Wine", "start": "09-09", "end": "11-21"}'::jsonb, ARRAY['30th Anniversary']::text[], 'kiosk-festival-favorites', 'food'),
  ('fw-pumpkin-cheesecake-mousse', 'Pumpkin Cheesecake Mousse Trifle', 'EPCOT', 'snack', 'PHILADELPHIA Cream Cheese with citrus sauce, spice cake, and cranberry streusel. Introduced in 2011 at Hops & Barley.', '$5.29', 5.29, null, null, null, null, '{"festival": "Food & Wine", "start": "09-09", "end": "11-21"}'::jsonb, ARRAY['30th Anniversary']::text[], 'kiosk-festival-favorites', 'food'),
  ('fw-frozen-s-mores', 'Frozen S''mores', 'EPCOT', 'snack', 'Chocolate milkshake with marshmallow syrup, mini marshmallows, chocolate shavings, and graham cracker. Non-alcoholic.', '$5.29', 5.29, null, null, null, null, '{"festival": "Food & Wine", "start": "09-09", "end": "11-21"}'::jsonb, null, 'kiosk-festival-favorites', 'drink'),
  ('fw-frozen-apple-blossom', 'Frozen Apple Blossom', 'EPCOT', 'snack', 'Apple cider, Seagram''s Ginger Ale, Hartley Apple VSOP Brandy, mini marshmallows, and maple syrup.', '$16.50', 16.5, null, null, null, null, '{"festival": "Food & Wine", "start": "09-09", "end": "11-21"}'::jsonb, null, 'kiosk-festival-favorites', 'drink'),
  ('fw-buffalo-dill-pickle-wings', 'Buffalo-Dill Pickle Wings', 'EPCOT', 'snack', 'Pilgrim''s Jumbo Wings with house-made pickle ranch.', '$7.79', 7.79, null, null, null, null, '{"festival": "Food & Wine", "start": "08-27", "end": "11-21"}'::jsonb, null, 'kiosk-brew-wing-lab-at-the-odyssey', 'food'),
  ('fw-carolina-reaper-pepper-curry', 'Carolina Reaper Pepper-Curry Wings', 'EPCOT', 'snack', 'Unnecessarily spicy — Carolina Reaper Pepper-Curry with creamy cucumber raita. Not for the faint-hearted.', '$7.79', 7.79, null, null, null, null, '{"festival": "Food & Wine", "start": "08-27", "end": "11-21"}'::jsonb, null, 'kiosk-brew-wing-lab-at-the-odyssey', 'food'),
  ('fw-garlic-parmesan-wings', 'Garlic-Parmesan Wings', 'EPCOT', 'snack', 'Classic garlic-parmesan preparation on Pilgrim''s Jumbo Wings.', '$7.79', 7.79, null, null, null, null, '{"festival": "Food & Wine", "start": "08-27", "end": "11-21"}'::jsonb, null, 'kiosk-brew-wing-lab-at-the-odyssey', 'food'),
  ('fw-korean-barbecue-wings', 'Korean Barbecue Wings', 'EPCOT', 'snack', 'Gochujang BBQ sauce with toasted sesame. A new addition to the wing lineup.', '$7.79', 7.79, null, null, null, null, '{"festival": "Food & Wine", "start": "08-27", "end": "11-21"}'::jsonb, null, 'kiosk-brew-wing-lab-at-the-odyssey', 'food'),
  ('fw-sweet-chile-lime-plant-based', 'Sweet Chile-Lime Plant-based Chicken Strips', 'EPCOT', 'snack', 'Plant-based chicken strips with cilantro crema and spicy peppers. New for 2026.', '$7.79', 7.79, null, null, null, null, '{"festival": "Food & Wine", "start": "08-27", "end": "11-21"}'::jsonb, ARRAY['Plant-based']::text[], 'kiosk-brew-wing-lab-at-the-odyssey', 'food'),
  ('fw-fried-pickle-spears', 'Fried Pickle Spears', 'EPCOT', 'snack', 'With dill ranch. A crowd-pleasing shareable.', '$5.79', 5.79, null, null, null, null, '{"festival": "Food & Wine", "start": "08-27", "end": "11-21"}'::jsonb, null, 'kiosk-brew-wing-lab-at-the-odyssey', 'food'),
  ('fw-pickle-milkshake', 'Pickle Milkshake', 'EPCOT', 'snack', 'Non-alcoholic. A fan-favorite novelty since 2023 — more drinkable than it sounds.', '$6.49', 6.49, null, null, null, null, '{"festival": "Food & Wine", "start": "08-27", "end": "11-21"}'::jsonb, null, 'kiosk-brew-wing-lab-at-the-odyssey', 'drink'),
  ('fw-frozen-pomegranate-raspberry', 'Frozen Pomegranate & Raspberry Tea', 'EPCOT', 'snack', 'Twinings Pomegranate & Raspberry Herbal Tea with orange ice cream molecules. Non-alcoholic, kid-friendly.', '$5.19', 5.19, null, null, null, null, '{"festival": "Food & Wine", "start": "08-27", "end": "11-21"}'::jsonb, null, 'kiosk-brew-wing-lab-at-the-odyssey', 'drink'),
  ('fw-crab-cake', 'Crab Cake', 'EPCOT', 'snack', 'With tropical fruit chutney, mustard sauce, and micro celery.', '$7.49', 7.49, null, null, null, null, '{"festival": "Food & Wine", "start": "10-02", "end": "11-21"}'::jsonb, null, 'kiosk-coastal-eats', 'food'),
  ('fw-seafood-pot-pie', 'Seafood Pot Pie', 'EPCOT', 'snack', 'Shrimp, scallops, and lobster bisque topped with puff pastry.', '$7.49', 7.49, null, null, null, null, '{"festival": "Food & Wine", "start": "10-02", "end": "11-21"}'::jsonb, null, 'kiosk-coastal-eats', 'food'),
  ('fw-basil-pesto-chicken-dumplings', 'Basil Pesto Chicken Dumplings', 'EPCOT', 'snack', 'Chicken dumplings with basil pesto, fonduta, tomato confit, and balsamic. New for 2026.', '$5.99', 5.99, null, null, null, null, '{"festival": "Food & Wine", "start": "08-27", "end": "11-21"}'::jsonb, null, 'kiosk-gyozas-of-the-galaxy', 'food'),
  ('fw-street-corn-style-dumplings', 'Street Corn-style Dumplings', 'EPCOT', 'snack', 'Chicken dumplings with tomatillo salsa verde, street corn salad, cotija, lime crema, and cilantro.', '$5.99', 5.99, null, null, null, null, '{"festival": "Food & Wine", "start": "08-27", "end": "11-21"}'::jsonb, null, 'kiosk-gyozas-of-the-galaxy', 'food'),
  ('fw-edamame-dumplings', 'Edamame Dumplings', 'EPCOT', 'snack', 'Butternut squash purée, caramelized onions, sage, and walnut-toasted garlic aïoli. New for 2026.', '$5.29', 5.29, null, null, null, null, '{"festival": "Food & Wine", "start": "08-27", "end": "11-21"}'::jsonb, ARRAY['Plant-based']::text[], 'kiosk-gyozas-of-the-galaxy', 'food'),
  ('fw-rodizio-style-grilled-beef', 'Rodizio-style Grilled Beef Skewer', 'EPCOT', 'snack', 'With marble potatoes, charred shallots, roasted baby peppers, and chimichurri. Introduced in 2009 at Argentina.', '$6.99', 6.99, null, null, null, null, '{"festival": "Food & Wine", "start": "08-27", "end": "11-21"}'::jsonb, ARRAY['30th Anniversary']::text[], 'kiosk-flavors-from-fire', 'food'),
  ('fw-smoked-corned-beef', 'Smoked Corned Beef', 'EPCOT', 'snack', 'With house-made potato chips, cheese curds, pickled onions, and beer cheese fondue.', '$6.49', 6.49, null, null, null, null, '{"festival": "Food & Wine", "start": "08-27", "end": "11-21"}'::jsonb, null, 'kiosk-flavors-from-fire', 'food'),
  ('fw-smoked-chocolate-bread-pudding', 'Smoked Chocolate Bread Pudding', 'EPCOT', 'snack', 'Chocolate ganache, vanilla bean-bourbon sauce, and smoked sea salt. New for 2026.', '$4.99', 4.99, null, null, null, null, '{"festival": "Food & Wine", "start": "08-27", "end": "11-21"}'::jsonb, null, 'kiosk-flavors-from-fire', 'food'),
  ('fw-swine-brine', 'Swine Brine', 'EPCOT', 'snack', 'Jim Beam Bourbon, apple-cinnamon cider, lemon juice, and Dijon mustard topped with a pork wing. A signature Food & Wine cocktail.', '$13.00', 13.0, null, null, null, null, '{"festival": "Food & Wine", "start": "08-27", "end": "11-21"}'::jsonb, null, 'kiosk-flavors-from-fire', 'drink'),
  ('fw-adobo-yuca-fries', 'Adobo Yuca Fries', 'EPCOT', 'snack', 'With plant-based garlic-cilantro aïoli.', '$5.79', 5.79, null, null, null, null, '{"festival": "Food & Wine", "start": "08-27", "end": "11-21"}'::jsonb, ARRAY['Plant-based']::text[], 'kiosk-the-fry-basket', 'food'),
  ('fw-fry-flight', 'Fry Flight', 'EPCOT', 'snack', 'Three fry styles: sea salt-malt vinegar, truffle-parmesan with black garlic-truffle aïoli, and sweet potato casserole fries with cinnamon sugar, candied pecans, and marshmallow cream. Great for sharing.', '$7.99', 7.99, null, null, null, null, '{"festival": "Food & Wine", "start": "08-27", "end": "11-21"}'::jsonb, null, 'kiosk-the-fry-basket', 'food'),
